// Zweck: Verarbeitet eine Meta-Nachricht und aktualisiert Geräteklasse, Fähigkeiten und Firmware.
// Eingaben: msg.sh (Routing-State), msg.payload (Rohpayload aus MQTT).
// Ergebnis: msg.payload mit aktualisiertem Geräteobjekt, msg.sqlite_batch für die Persistenzschicht.
// Seiteneffekt: Schreibt das aktualisierte Gerät in smarthome_runtime (global).
const topicHandlers = global.get("topicHandlers");
const result = topicHandlers.handleRoutedMessage(global.get("smarthome_runtime"), msg.sh, msg.payload);
if (!result || !result.payload || !result.payload.device) {
    node.warn("meta without device_id");
    return null;
}
global.set("smarthome_runtime", result.runtime);
msg.payload = result.payload;
msg.sqlite_batch = result.sqlite_batch || null;
return msg;

